class NeighborSum {
private:
    vector<vector<int>> grid;
    int n;
    unordered_map<int, pair<int, int>> pos;
public:
    NeighborSum(vector<vector<int>>& grid) : grid(grid), n(grid.size()) {
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < n; ++c) {
                pos[grid[r][c]] = {r, c};
            }
        }
    }

    int adjacentSum(int value) {
        auto [r, c] = pos[value];
        int total = 0;
        int dr[] = {-1, 1, 0, 0};
        int dc[] = {0, 0, -1, 1};
        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                total += grid[nr][nc];
            }
        }
        return total;
    }

    int diagonalSum(int value) {
        auto [r, c] = pos[value];
        int total = 0;
        int dr[] = {-1, -1, 1, 1};
        int dc[] = {-1, 1, -1, 1};
        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                total += grid[nr][nc];
            }
        }
        return total;
    }
};

class NeighborSum {
