    private int n;
    private Map<Integer, int[]> pos;

    public NeighborSum(int[][] grid) {
        this.grid = grid;
        this.n = grid.length;
        this.pos = new HashMap<>();
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < n; ++c) {
                pos.put(grid[r][c], new int[]{r, c});
            }
        }
    }

    public int adjacentSum(int value) {
        int[] p = pos.get(value);
        int r = p[0], c = p[1];
        int total = 0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        for (int i = 0; i < 4; ++i) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                total += grid[nr][nc];
            }
        }
        return total;
    }

    public int diagonalSum(int value) {
        int[] p = pos.get(value);
        int r = p[0], c = p[1];
        int total = 0;
        int[] dr = {-1, -1, 1, 1};
        int[] dc = {-1, 1, -1, 1};
        for (int i = 0; i < 4; ++i) {
